      <CollapsibleContent
        className="ml-3.5 flex flex-col gap-0.5 border-border/60 border-l pl-1.5"
        data-slot="file-explorer-tree-folder-content"
      >
        {node.children?.map((child) => (
          <FileExplorerTreeNode
            depth={depth + 1}
            key={child.path}
            node={child}
            onOpenFile={onOpenFile}
          />
        ))}
      </CollapsibleContent>
    </Collapsible>
  );
}

"use client";

import { useCallback, useState } from "react";

export type ChatSidePanelTool = "files" | "browser" | "terminal";

export type ChatSidePanelTab =
  | { id: string; type: ChatSidePanelTool }
  | { id: string; type: "file"; path: string; name: string };

export function useChatSidePanel() {
  const [panelOpen, setPanelOpen] = useState(false);
  const [tabs, setTabs] = useState<ChatSidePanelTab[]>([]);
  const [activeTabId, setActiveTabId] = useState<string | null>(null);

  const openPanel = useCallback(() => {
    setPanelOpen(true);
  }, []);

  const closePanel = useCallback(() => {
    setPanelOpen(false);
    setTabs([]);
    setActiveTabId(null);
  }, []);

  const togglePanel = useCallback(() => {
    if (panelOpen) {
      closePanel();
    } else {
      openPanel();
    }
  }, [closePanel, openPanel, panelOpen]);

  const openToolTab = useCallback(
    (tool: ChatSidePanelTool) => {
      setPanelOpen(true);
      const existing = tabs.find((tab) => tab.type === tool);
      if (existing) {
        setActiveTabId(existing.id);
        return;
      }

      const id = crypto.randomUUID();
      setTabs((current) => [...current, { id, type: tool }]);
      setActiveTabId(id);
    },
    [tabs]
  );

  const closeTab = useCallback(
    (tabId: string) => {
      const closedIndex = tabs.findIndex((tab) => tab.id === tabId);
      const next = tabs.filter((tab) => tab.id !== tabId);
      setTabs(next);
      if (activeTabId === tabId) {
        const fallback = next[closedIndex] ?? next[closedIndex - 1];
        setActiveTabId(fallback?.id ?? null);
      }
    },
    [activeTabId, tabs]
  );

  const activeTab = tabs.find((tab) => tab.id === activeTabId) ?? null;

  return {
    panelOpen,
    tabs,
    activeTab,
    activeTabId,
    openPanel,
    closePanel,
    togglePanel,
    openToolTab,
    closeTab,
    setActiveTabId,
  };
}

